{
  "title": "Discussion on tax filing, domain purchase, app profitability and source code security",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing shortcuts and risks",
      "claims": [
        {
          "text": "Using a relative (aunt) to correct tax declarations can avoid larger penalties.",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is correctly matching columns in the declaration, not the calculation itself.",
          "evidence": [5, 8]
        },
        {
          "text": "The whole procedure can take about an hour with Excel.",
          "evidence": [5]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase skepticism",
      "claims": [
        {
          "text": "Someone mentions they haven't even bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "Buying a calculator (presumably tax calculator) is seen as a prerequisite for having money to buy a domain.",
          "evidence": [4]
        },
        {
          "text": "A participant doubts anyone will actually purchase the domain.",
          "evidence": [9]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a simple web/app product",
      "claims": [
        {
          "text": "Web platforms are less profitable than Android/iOS, with low SEO and no external traffic sources.",
          "evidence": [11]
        },
        {
          "text": "Successful rapid delivery (under a week) with a cross‑platform stack (Flutter) is suggested as a way to earn.",
          "evidence": [12]
        },
        {
          "text": "The speaker doubts the product will sell, betting it won't get buyers within a month.",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience composition has shifted, with fewer technical/managerial posts.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Security of source code and passwords in the project",
      "claims": [
        {
          "text": "The project stores a single password in local storage as a 100% discount promo code.",
          "evidence": [20]
        },
        {
          "text": "A question is raised about finding the password via source code search.",
          "evidence": [21]
        },
        {
          "text": "Another participant mocks the idea of paying 299 UAH for such a setup.",
          "evidence": [22]
        },
        {
          "text": "The code is described as being in a bundle, implying limited visibility.",
          "evidence": [23]
        },
        {
          "text": "One user claims most LinkedIn users could hack the thing without problems.",
          "evidence": [28]
        },
        {
          "text": "The app is positioned as a local‑first app with USD/UAH rates refreshed every 5 minutes and calculations done in the browser.",
          "evidence": [29]
        },
        {
          "text": "The project is portrayed as a free “vibe‑code” experiment with no serious intent.",
          "evidence": [30]
        },
        {
          "text": "A participant calls the author a scammer.",
          "evidence": [32]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
